<section class="page-heading"><div><p class="eyebrow">ÉTAT ET ENTRETIEN DES PIÈCES</p><h1>Gestion du linge</h1><p class="subheading">Les disponibilités sont partagées avec le catalogue et le compositeur de tenues.</p></div></section>
<form class="filter-bar" method="get"><input type="hidden" name="page" value="laundry"><select name="status"><option value="">Tous les états</option><?php foreach(['laundry'=>'Au lavage','repair'=>'À réparer','unavailable'=>'Indisponible','available'=>'Disponible'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $selectedStatus===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><button class="button secondary">Filtrer</button></form>
<?php if(!$clothes): ?><div class="empty-state"><h3>Aucun vêtement pour ce filtre</h3><a class="button primary" href="<?= e(url('clothes')) ?>">Ouvrir ma garde-robe</a></div><?php else: ?><div class="laundry-list"><?php foreach($clothes as $item): ?><article class="laundry-row"><div class="laundry-thumb"><?php if($item['image_path']): ?><img src="<?= e(APP_BASE_URL.'/'.$item['image_path']) ?>" alt=""><?php else: ?>GRINGO<?php endif; ?></div><div class="laundry-name"><small><?= e($item['label_name']) ?></small><b><?= e($item['name']) ?></b><span><?= $item['last_washed_at']?'Dernier lavage : '.e(date('d.m.Y',strtotime($item['last_washed_at']))):'Aucun lavage enregistré' ?></span></div><form method="post" action="<?= e(url('laundry-status')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($item['id']) ?>"><input type="hidden" name="filter" value="<?= e($selectedStatus) ?>"><input name="note" maxlength="255" placeholder="Note (facultative)"><select name="status" aria-label="Nouvel état"><?php foreach(['available'=>'Disponible','laundry'=>'Au lavage','repair'=>'À réparer','unavailable'=>'Indisponible'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $item['status']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><button class="button secondary">Enregistrer</button></form></article><?php endforeach; ?></div><?php endif; ?>
<section class="history-panel"><p class="eyebrow">HISTORIQUE RÉCENT</p><h2>Cycles de lavage</h2><?php if(!$history): ?><p class="subheading">Les cycles terminés apparaîtront ici.</p><?php else: foreach($history as $event): ?><div class="detail-row"><span><?= e($event['clothing_name']) ?> · <?= e(date('d.m.Y',strtotime($event['started_at']))) ?></span><strong><?= $event['completed_at']?'Terminé le '.e(date('d.m.Y',strtotime($event['completed_at']))):'En cours' ?></strong></div><?php endforeach; endif; ?></section>
